// Open files on decode workers.
export class Decoders {
  constructor(spawn, max) {
    this.spawn = spawn;
    this.max = max;
    this.workers = [];
  }

  pick() {
    const free = this.workers.find((w) => w.queue.length < 4);
    if (free) return free;
    if (this.workers.length < this.max) {
      const worker = this.spawn();
      this.workers.push(worker);
      return worker;
    }
    return this.workers.reduce((a, b) => (a.queue.length <= b.queue.length ? a : b));
  }

  open(file) {
    const worker = this.pick();
    worker.files.add(file);
    return worker.post({ op: 'open', file });
  }
}
